static int parse_bool(js *j,int *out){ skip_ws(j); if(j->n>=4&&memcmp(j->s,"true",4)==0){*out=1;j->s+=4;j->n-=4;return 1;} if(j->n>=5&&memcmp(j->s,"false",5)==0){*out=0;j->s+=5;j->n-=5;return 1;} return 0; }
static int obj_find(js obj,const char *name,js *val){ js j; const char *k; unsigned long kl; j=obj; if(!consume(&j,'{')) return 0; skip_ws(&j); if(consume(&j,'}')) return 0; for(;;){ if(!parse_string(&j,&k,&kl)) return 0; if(!consume(&j,':')) return 0; if(streqn(k,name,kl)){ *val=j; return 1; } skip_value(&j); skip_ws(&j); if(consume(&j,'}')) return 0; if(!consume(&j,',')) return 0; } }
static int val_int(js obj,const char *name,int def){ js v; long x; if(obj_find(obj,name,&v)&&parse_int(&v,&x)) return (int)x; return def; }
static unsigned long val_ulong(js obj,const char *name,unsigned long def){ js v; long x; if(obj_find(obj,name,&v)&&parse_int(&v,&x)&&x>=0) return (unsigned long)x; return def; }
static void val_str(js obj,const char *name,char *dst,unsigned long cap){ js v; const char *s; unsigned long l; if(obj_find(obj,name,&v)&&parse_string(&v,&s,&l)) copy_str(dst,cap,s,l); }
static int val_bool(js obj,const char *name,int def){ js v; int b; if(obj_find(obj,name,&v)&&parse_bool(&v,&b)) return b; return def; }
static gltf3d_fx val_fx(js obj,const char *name,gltf3d_fx def){ js v; gltf3d_fx x; if(obj_find(obj,name,&v)&&parse_fx(&v,&x)) return x; return def; }
static void val_fx_arr(js obj,const char *name,gltf3d_fx *arr,int max){ js v; int i; if(!obj_find(obj,name,&v)||!consume(&v,'[')) return; for(i=0;i<max;i++){ if(!parse_fx(&v,&arr[i])) return; skip_ws(&v); if(!consume(&v,',')) return; } }
static int type_count(js obj){ char t[16]; t[0]=0; val_str(obj,"type",t,16); if(strcmp(t,"SCALAR")==0) return 1; if(strcmp(t,"VEC2")==0) return 2; if(strcmp(t,"VEC3")==0) return 3; if(strcmp(t,"VEC4")==0) return 4; if(strcmp(t,"MAT2")==0) return 4; if(strcmp(t,"MAT3")==0) return 9; if(strcmp(t,"MAT4")==0) return 16; return 1; }
static int path_code(js obj){ char p[24]; p[0]=0; val_str(obj,"path",p,24); if(strcmp(p,"translation")==0) return GLTF3D_TARGET_TRANSLATION; if(strcmp(p,"rotation")==0) return GLTF3D_TARGET_ROTATION; if(strcmp(p,"scale")==0) return GLTF3D_TARGET_SCALE; if(strcmp(p,"weights")==0) return GLTF3D_TARGET_WEIGHTS; return 0; }
static int interp_code(js obj){ char p[24]; p[0]=0; val_str(obj,"interpolation",p,24); if(strcmp(p,"STEP")==0) return GLTF3D_INTERP_STEP; if(strcmp(p,"CUBICSPLINE")==0) return GLTF3D_INTERP_CUBICSPLINE; return GLTF3D_INTERP_LINEAR; }
static int meshopt_mode_code(js obj){ char p[32]; p[0]=0; val_str(obj,"mode",p,32); if(strcmp(p,"ATTRIBUTES")==0) return 1; if(strcmp(p,"TRIANGLES")==0) return 2; if(strcmp(p,"INDICES")==0) return 3; if(strcmp(p,"WEIGHTS")==0) return 4; return 0; }
static int meshopt_filter_code(js obj){ char p[32]; p[0]=0; val_str(obj,"filter",p,32); if(p[0]==0||strcmp(p,"NONE")==0) return 0; if(strcmp(p,"OCTAHEDRAL")==0) return 1; if(strcmp(p,"QUATERNION")==0) return 2; if(strcmp(p,"EXPONENTIAL")==0) return 3; return 0; }
static void parse_meshopt_bv(gltf3d_bufferview*b,js o){ js ext,mo; if(obj_find(o,"extensions",&ext)&&obj_find(ext,"EXT_meshopt_compression",&mo)){ b->has_meshopt=1; b->meshopt_buffer=val_int(mo,"buffer",-1); b->meshopt_byte_offset=val_ulong(mo,"byteOffset",0); b->meshopt_byte_length=val_ulong(mo,"byteLength",0); b->meshopt_byte_stride=val_ulong(mo,"byteStride",0); b->meshopt_count=val_ulong(mo,"count",0); b->meshopt_mode=meshopt_mode_code(mo); b->meshopt_filter=meshopt_filter_code(mo); } }
static void parse_texture_basisu(gltf3d_texture*t,js o){ js ext,ba; t->basisu_source=-1; if(obj_find(o,"extensions",&ext)&&obj_find(ext,"KHR_texture_basisu",&ba)) t->basisu_source=val_int(ba,"source",-1); }

void gltf3d_asset_init(gltf3d_asset *a){ int i,k,t; if(!a) return; memset(a,0,sizeof(*a)); a->scene=-1; for(i=0;i<GLTF3D_MAX_BUFFERS;i++){ a->buffers[i].uri[0]=0; } for(i=0;i<GLTF3D_MAX_ACCESSORS;i++){ a->accessors[i].buffer_view=-1; a->accessors[i].sparse_indices_buffer_view=-1; a->accessors[i].sparse_values_buffer_view=-1; } for(i=0;i<GLTF3D_MAX_PRIMITIVES;i++){ a->primitives[i].indices=-1; a->primitives[i].material=-1; a->primitives[i].mode=GLTF3D_MODE_TRIANGLES; a->primitives[i].draco_buffer_view=-1; for(k=0;k<GLTF3D_ATTR_COUNT;k++) a->primitives[i].draco_attributes[k]=-1; for(k=0;k<GLTF3D_ATTR_COUNT;k++) a->primitives[i].attributes[k]=-1; for(t=0;t<GLTF3D_MAX_MORPH_TARGETS;t++){ a->primitives[i].morph_targets[t][0]=-1; a->primitives[i].morph_targets[t][1]=-1; a->primitives[i].morph_targets[t][2]=-1; } } for(i=0;i<GLTF3D_MAX_NODES;i++){ a->nodes[i].mesh=-1; a->nodes[i].skin=-1; a->nodes[i].camera=-1; a->nodes[i].light=-1; a->nodes[i].translation[0]=0; a->nodes[i].translation[1]=0; a->nodes[i].translation[2]=0; a->nodes[i].rotation[0]=0; a->nodes[i].rotation[1]=0; a->nodes[i].rotation[2]=0; a->nodes[i].rotation[3]=GLTF3D_FX_ONE; a->nodes[i].scale[0]=GLTF3D_FX_ONE; a->nodes[i].scale[1]=GLTF3D_FX_ONE; a->nodes[i].scale[2]=GLTF3D_FX_ONE; } for(i=0;i<GLTF3D_MAX_MESHES;i++){ a->meshes[i].weights_accessor=-1; } for(i=0;i<GLTF3D_MAX_MATERIALS;i++){ a->materials[i].base_color[0]=GLTF3D_FX_ONE; a->materials[i].base_color[1]=GLTF3D_FX_ONE; a->materials[i].base_color[2]=GLTF3D_FX_ONE; a->materials[i].base_color[3]=GLTF3D_FX_ONE; a->materials[i].roughness=GLTF3D_FX_ONE; a->materials[i].metallic=0; a->materials[i].base_color_texture=-1; a->materials[i].metallic_roughness_texture=-1; a->materials[i].normal_texture=-1; a->materials[i].occlusion_texture=-1; a->materials[i].emissive_texture=-1; a->materials[i].alpha_mode=GLTF3D_ALPHA_OPAQUE; a->materials[i].alpha_cutoff=GLTF3D_FX_ONE/2; a->materials[i].normal_scale=GLTF3D_FX_ONE; a->materials[i].occlusion_strength=GLTF3D_FX_ONE; } for(i=0;i<GLTF3D_MAX_CAMERAS;i++){ a->cameras[i].type=0; } for(i=0;i<GLTF3D_MAX_LIGHTS;i++){ a->lights[i].type=0; a->lights[i].color[0]=GLTF3D_FX_ONE; a->lights[i].color[1]=GLTF3D_FX_ONE; a->lights[i].color[2]=GLTF3D_FX_ONE; a->lights[i].intensity=GLTF3D_FX_ONE; a->lights[i].range=0; a->lights[i].inner_cone_angle=0; a->lights[i].outer_cone_angle=GLTF3D_FX_ONE; } }

static int parse_array_objects(js root,const char *name,int (*cb)(gltf3d_asset*,js,void*),gltf3d_asset *a,void *u){ js arr,o; if(!obj_find(root,name,&arr)) return GLTF3D_OK; if(!consume(&arr,'[')) return GLTF3D_ERR_JSON; skip_ws(&arr); if(consume(&arr,']')) return GLTF3D_OK; for(;;){ o=arr; if(cb(a,o,u)!=GLTF3D_OK) return GLTF3D_ERR_LIMIT; skip_value(&arr); skip_ws(&arr); if(consume(&arr,']')) break; if(!consume(&arr,',')) return GLTF3D_ERR_JSON; } return GLTF3D_OK; }
static int cb_buffer(gltf3d_asset*a,js o,void*u){ const gltf3d_io*io=(const gltf3d_io*)u; int i=a->buffer_count; if(i>=GLTF3D_MAX_BUFFERS) return GLTF3D_ERR_LIMIT; a->buffers[i].byte_length=val_ulong(o,"byteLength",0); val_str(o,"uri",a->buffers[i].uri,GLTF3D_MAX_URI); if(a->buffers[i].uri[0]&&io&&io->load_uri){ const unsigned char*d; unsigned long n; if(io->load_uri(io->user,a->buffers[i].uri,&d,&n)==0){ a->buffers[i].data=d; a->buffers[i].data_length=n; } } a->buffer_count++; return GLTF3D_OK; }
static int cb_bv(gltf3d_asset*a,js o,void*u){ int i=a->buffer_view_count; (void)u; if(i>=GLTF3D_MAX_BUFFERVIEWS) return GLTF3D_ERR_LIMIT; a->buffer_views[i].buffer=val_int(o,"buffer",0); a->buffer_views[i].byte_offset=val_ulong(o,"byteOffset",0); a->buffer_views[i].byte_length=val_ulong(o,"byteLength",0); a->buffer_views[i].byte_stride=val_ulong(o,"byteStride",0); a->buffer_views[i].target=val_int(o,"target",0); parse_meshopt_bv(&a->buffer_views[i],o); a->buffer_view_count++; return GLTF3D_OK; }
static int cb_accessor(gltf3d_asset*a,js o,void*u){ js sp,idx,val; int i=a->accessor_count; (void)u; if(i>=GLTF3D_MAX_ACCESSORS) return GLTF3D_ERR_LIMIT; a->accessors[i].buffer_view=val_int(o,"bufferView",-1); a->accessors[i].byte_offset=val_ulong(o,"byteOffset",0); a->accessors[i].component_type=val_int(o,"componentType",0); a->accessors[i].normalized=val_bool(o,"normalized",0); a->accessors[i].count=val_ulong(o,"count",0); a->accessors[i].elem_count=type_count(o); val_fx_arr(o,"min",a->accessors[i].minv,16); val_fx_arr(o,"max",a->accessors[i].maxv,16); if(obj_find(o,"sparse",&sp)){ a->accessors[i].sparse_count=val_ulong(sp,"count",0); if(obj_find(sp,"indices",&idx)){ a->accessors[i].sparse_indices_buffer_view=val_int(idx,"bufferView",-1); a->accessors[i].sparse_indices_byte_offset=val_ulong(idx,"byteOffset",0); a->accessors[i].sparse_indices_component_type=val_int(idx,"componentType",0); } if(obj_find(sp,"values",&val)){ a->accessors[i].sparse_values_buffer_view=val_int(val,"bufferView",-1); a->accessors[i].sparse_values_byte_offset=val_ulong(val,"byteOffset",0); } } a->accessor_count++; return GLTF3D_OK; }
static void parse_texinfo(js o,const char*n,int *dst){ js v; if(obj_find(o,n,&v)) *dst=val_int(v,"index",-1); }
static void parse_alpha_mode(js o,int *dst){ char m[16]; m[0]=0; val_str(o,"alphaMode",m,16); if(strcmp(m,"MASK")==0) *dst=GLTF3D_ALPHA_MASK; else if(strcmp(m,"BLEND")==0) *dst=GLTF3D_ALPHA_BLEND; else if(strcmp(m,"OPAQUE")==0) *dst=GLTF3D_ALPHA_OPAQUE; }
static int cb_material(gltf3d_asset*a,js o,void*u){ js pbr,nt,ot; int i=a->material_count; (void)u; if(i>=GLTF3D_MAX_MATERIALS) return GLTF3D_ERR_LIMIT; if(obj_find(o,"pbrMetallicRoughness",&pbr)){ val_fx_arr(pbr,"baseColorFactor",a->materials[i].base_color,4); a->materials[i].metallic=val_fx(pbr,"metallicFactor",0); a->materials[i].roughness=val_fx(pbr,"roughnessFactor",GLTF3D_FX_ONE); parse_texinfo(pbr,"baseColorTexture",&a->materials[i].base_color_texture); parse_texinfo(pbr,"metallicRoughnessTexture",&a->materials[i].metallic_roughness_texture); }
 parse_texinfo(o,"normalTexture",&a->materials[i].normal_texture); if(obj_find(o,"normalTexture",&nt)) a->materials[i].normal_scale=val_fx(nt,"scale",GLTF3D_FX_ONE); parse_texinfo(o,"occlusionTexture",&a->materials[i].occlusion_texture); if(obj_find(o,"occlusionTexture",&ot)) a->materials[i].occlusion_strength=val_fx(ot,"strength",GLTF3D_FX_ONE); parse_texinfo(o,"emissiveTexture",&a->materials[i].emissive_texture); val_fx_arr(o,"emissiveFactor",a->materials[i].emissive,3); parse_alpha_mode(o,&a->materials[i].alpha_mode); a->materials[i].alpha_cutoff=val_fx(o,"alphaCutoff",GLTF3D_FX_ONE/2); a->materials[i].double_sided=val_bool(o,"doubleSided",0); a->material_count++; return GLTF3D_OK; }
static int cb_image(gltf3d_asset*a,js o,void*u){ int i=a->image_count; (void)u; if(i>=GLTF3D_MAX_IMAGES) return GLTF3D_ERR_LIMIT; val_str(o,"uri",a->images[i].uri,GLTF3D_MAX_URI); val_str(o,"mimeType",a->images[i].mime_type,32); a->images[i].buffer_view=val_int(o,"bufferView",-1); a->image_count++; return GLTF3D_OK; }
static int cb_texture(gltf3d_asset*a,js o,void*u){ int i=a->texture_count; (void)u; if(i>=GLTF3D_MAX_TEXTURES) return GLTF3D_ERR_LIMIT; a->textures[i].sampler=val_int(o,"sampler",-1); a->textures[i].source=val_int(o,"source",-1); parse_texture_basisu(&a->textures[i],o); a->texture_count++; return GLTF3D_OK; }
static int cb_sampler(gltf3d_asset*a,js o,void*u){ int i=a->sampler_count; (void)u; if(i>=GLTF3D_MAX_SAMPLERS) return GLTF3D_ERR_LIMIT; a->samplers[i].mag_filter=val_int(o,"magFilter",0); a->samplers[i].min_filter=val_int(o,"minFilter",0); a->samplers[i].wrap_s=val_int(o,"wrapS",10497); a->samplers[i].wrap_t=val_int(o,"wrapT",10497); a->sampler_count++; return GLTF3D_OK; }
static int attr_id(const char*s,unsigned long n){ if(streqn(s,"POSITION",n)) return GLTF3D_ATTR_POSITION; if(streqn(s,"NORMAL",n)) return GLTF3D_ATTR_NORMAL; if(streqn(s,"TANGENT",n)) return GLTF3D_ATTR_TANGENT; if(streqn(s,"TEXCOORD_0",n)) return GLTF3D_ATTR_TEXCOORD_0; if(streqn(s,"TEXCOORD_1",n)) return GLTF3D_ATTR_TEXCOORD_1; if(streqn(s,"COLOR_0",n)) return GLTF3D_ATTR_COLOR_0; if(streqn(s,"JOINTS_0",n)) return GLTF3D_ATTR_JOINTS_0; if(streqn(s,"WEIGHTS_0",n)) return GLTF3D_ATTR_WEIGHTS_0; return -1; }
static void parse_attrs(gltf3d_primitive*p,js o){ js at; const char*k; unsigned long kl; long v; int id; if(!obj_find(o,"attributes",&at)||!consume(&at,'{')) return; skip_ws(&at); if(consume(&at,'}')) return; for(;;){ if(!parse_string(&at,&k,&kl)) return; if(!consume(&at,':')) return; id=attr_id(k,kl); if(parse_int(&at,&v)&&id>=0) p->attributes[id]=(int)v; else skip_value(&at); skip_ws(&at); if(consume(&at,'}')) return; if(!consume(&at,',')) return; } }
static void parse_morph_targets(gltf3d_primitive*p,js o){ js arr,t; if(!obj_find(o,"targets",&arr)||!consume(&arr,'[')) return; skip_ws(&arr); if(consume(&arr,']')) return; for(;;){ int ti=p->morph_target_count; if(ti>=GLTF3D_MAX_MORPH_TARGETS) return; t=arr; p->morph_targets[ti][0]=val_int(t,"POSITION",-1); p->morph_targets[ti][1]=val_int(t,"NORMAL",-1); p->morph_targets[ti][2]=val_int(t,"TANGENT",-1); p->morph_target_count++; skip_value(&arr); skip_ws(&arr); if(consume(&arr,']')) return; if(!consume(&arr,',')) return; } }
static void parse_mesh_weights(gltf3d_mesh*m,js o){ js w; int i; if(!obj_find(o,"weights",&w)||!consume(&w,'[')) return; for(i=0;i<GLTF3D_MAX_MORPH_TARGETS;i++){ if(!parse_fx(&w,&m->weights[i])) return; m->weight_count++; skip_ws(&w); if(!consume(&w,',')) return; } }
static void parse_draco(gltf3d_primitive*p,js o){ js ext,dra,at; if(obj_find(o,"extensions",&ext)&&obj_find(ext,"KHR_draco_mesh_compression",&dra)){ p->has_draco=1; p->draco_buffer_view=val_int(dra,"bufferView",-1); if(obj_find(dra,"attributes",&at)){ p->draco_attributes[GLTF3D_ATTR_POSITION]=val_int(at,"POSITION",-1); p->draco_attributes[GLTF3D_ATTR_NORMAL]=val_int(at,"NORMAL",-1); p->draco_attributes[GLTF3D_ATTR_TANGENT]=val_int(at,"TANGENT",-1); p->draco_attributes[GLTF3D_ATTR_TEXCOORD_0]=val_int(at,"TEXCOORD_0",-1); p->draco_attributes[GLTF3D_ATTR_TEXCOORD_1]=val_int(at,"TEXCOORD_1",-1); p->draco_attributes[GLTF3D_ATTR_COLOR_0]=val_int(at,"COLOR_0",-1); p->draco_attributes[GLTF3D_ATTR_JOINTS_0]=val_int(at,"JOINTS_0",-1); p->draco_attributes[GLTF3D_ATTR_WEIGHTS_0]=val_int(at,"WEIGHTS_0",-1); } } }
